define(["core/ajax"],function(Ajax){const init=function(flexbookId){document.querySelectorAll(".flexbook-content-accordion").forEach(function(block){const visited=new Set;block.querySelectorAll(".accordion-button").forEach(function(button){button.addEventListener("click",function(){const panel=button.closest(".accordion-item").querySelector(".accordion-collapse");const open=!panel.classList.contains("show");panel.classList.toggle("show",open);button.classList.toggle("collapsed",!open);button.setAttribute("aria-expanded",open?"true":"false");if(open){visited.add(Number(button.dataset.itemIndex));Ajax.call([{methodname:"mod_flexbook_mark_content_completed",args:{flexbookid:flexbookId,contentid:Number(block.dataset.contentId),metric:visited.size,details:JSON.stringify({visited:Array.from(visited)})}}])[0].catch(function(){})}})})})};return{init:init}});